# -*- coding: utf-8 -*-
"""
brand.py -- LegalVerifyDZ
Official logo assets, embedded so the app needs no image files at deploy time.
All helpers return single-line <img> data-URI tags (safe inside st.markdown HTML).
"""

import base64
import io

_ICON = ""
_ICON_DARK = ""
_HORIZONTAL = ""
_HORIZONTAL_DARK = ""
_FAVICON_PNG = ""


def _img(data, style):
    return '<img src="data:image/svg+xml;base64,' + data + '" alt="LegalVerifyDZ" style="' + style + '" />'


def _margin(align):
    return {"center": "0 auto", "start": "0", "end": "0 0 0 auto"}.get(align, "0 auto")


def icon(size=56, dark=False, align="center"):
    """Shield mark only. dark=True for dark backgrounds."""
    return _img(_ICON_DARK if dark else _ICON,
                "display:block;margin:%s;width:%spx;height:%spx;" % (_margin(align), size, size))


def horizontal(width=240, dark=False, align="center"):
    """Mark + wordmark. dark=True for dark backgrounds."""
    return _img(_HORIZONTAL_DARK if dark else _HORIZONTAL,
                "display:block;margin:%s;width:%spx;max-width:100%%;height:auto;" % (_margin(align), width))


def favicon():
    """PIL image for st.set_page_config(page_icon=...)."""
    from PIL import Image
    return Image.open(io.BytesIO(base64.b64decode(_FAVICON_PNG)))
